				WebhookType:   pulumi.String("WEBHOOK_ROOTLY"),
				Template: pulumi.String(`{
  \"alert_type\": \"{{ALERT_TYPE}}\",
  \"check_id\": \"{{CHECK_ID}}\",
  \"check_result_id\": \"{{CHECK_RESULT_ID}}\",
