import * as pulumi from "@pulumi/pulumi";
import * as checkly from "@checkly/pulumi";

// Basic API check
const exampleCheck = new checkly.ApiCheck("example_check", {
    name: "Example check",
    activated: true,
    shouldFail: false,
    frequency: 1,
    useGlobalAlertSettings: true,
    locations: ["us-west-1"],
    request: {
        url: "https://api.example.com/",
        followRedirects: true,
        skipSsl: false,
        assertions: [{
            source: "STATUS_CODE",
            comparison: "EQUALS",
            target: "200",
        }],
    },
});
// A more complex example using more assertions and setting alerts
const exampleCheck2 = new checkly.ApiCheck("example_check_2", {
    name: "Example API check 2",
    activated: true,
    shouldFail: true,
    frequency: 1,
    degradedResponseTime: 5000,
    maxResponseTime: 10000,
    locations: [
        "us-west-1",
        "ap-northeast-1",
        "ap-south-1",
    ],
    alertSettings: {
        escalationType: "RUN_BASED",
        runBasedEscalation: {
            failedRunThreshold: 1,
        },
        reminders: {
            amount: 1,
        },
    },
    retryStrategy: {
        type: "FIXED",
        baseBackoffSeconds: 60,
        maxDurationSeconds: 600,
        maxRetries: 3,
        sameRegion: false,
    },
    request: {
        followRedirects: true,
        skipSsl: false,
        url: "http://api.example.com/",
        queryParameters: {
            search: "foo",
        },
        headers: {
            "X-Bogus": "bogus",
        },
        assertions: [
            {
                source: "JSON_BODY",
                property: "code",
                comparison: "HAS_VALUE",
                target: "authentication.failed",
            },
            {
                source: "STATUS_CODE",
                property: "",
                comparison: "EQUALS",
                target: "401",
            },
        ],
        basicAuth: {
            username: "monitoring",
            password: "not-the-password",
        },
    },
});
// A high frequency API check running every 30 seconds
const highFrequencyCheck = new checkly.ApiCheck("high_frequency_check", {
    name: "High frequency check",
    activated: true,
    frequency: 0,
    frequencyOffset: 30,
    locations: ["us-west-1"],
    request: {
        url: "https://api.example.com/health",
        assertions: [{
            source: "STATUS_CODE",
            comparison: "EQUALS",
            target: "200",
        }],
    },
});
// Connecting checks to alert channels
const emailAc1 = new checkly.AlertChannel("email_ac1", {email: {
    address: "info1@example.com",
}});
const emailAc2 = new checkly.AlertChannel("email_ac2", {email: {
    address: "info2@example.com",
}});
