				&checkly.CheckAlertChannelSubscriptionArgs{
					ChannelId: emailAc2.ID().ToStringOutput().ApplyT(strconv.Atoi).(pulumi.IntOutput),
					Activated: pulumi.Bool(true),
				},
			},
		})
		if err != nil {
			return err
		}
		return nil
	})
