    name: "My test group 1",
    activated: true,
    muted: false,
    tags: ["auto"],
    locations: ["eu-west-1"],
    concurrency: 3,
    apiCheckDefaults: {
        url: "http://example.com/",
        headers: {
            "X-Test": "foo",
        },
        queryParameters: {
            query: "foo",
        },
        assertions: [
            {
                source: "STATUS_CODE",
                property: "",
                comparison: "EQUALS",
                target: "200",
            },
            {
                source: "TEXT_BODY",
                property: "",
                comparison: "CONTAINS",
                target: "welcome",
            },
        ],
        basicAuth: {
            username: "user",
            password: "pass",
        },
    },
    environmentVariables: [
        {
            key: "TEST_ENV_VAR",
            value: "Hello world",
            locked: false,
        },
        {
            key: "ADDITIONAL_ENV_VAR",
            value: "test value",
            locked: true,
        },
