checkly:index/sslMonitor:SslMonitor.description:
SSL monitors check the TLS certificate of a host and alert before it expires or violates a security baseline.

## Example Usage

<!--Start PulumiCodeChooser -->
```typescript
import * as pulumi from "@pulumi/pulumi";
import * as checkly from "@checkly/pulumi";

// Basic SSL/TLS certificate monitor
const example_ssl_monitor = new checkly.SslMonitor("example-ssl-monitor", {
    name: "Example SSL monitor",
    activated: true,
    frequency: 60,
    useGlobalAlertSettings: true,
    locations: ["us-west-1"],
    request: {
        hostname: "api.checklyhq.com",
        port: 443,
        alertDaysBeforeExpiry: 30,
    },
});
// A more complex example with response-time thresholds, a custom security
// baseline and certificate assertions
const example_ssl_monitor_2 = new checkly.SslMonitor("example-ssl-monitor-2", {
    name: "Example SSL monitor 2",
    activated: true,
    frequency: 60,
    degradedResponseTime: 3000,
    maxResponseTime: 10000,
    locations: [
        "us-west-1",
        "eu-central-1",
    ],
    alertSettings: {
        escalationType: "RUN_BASED",
        runBasedEscalation: {
            failedRunThreshold: 1,
        },
        reminders: {
            amount: 1,
        },
    },
    request: {
        hostname: "api.checklyhq.com",
        port: 443,
        serverName: "api.checklyhq.com",
        ipFamily: "IPv4",
        skipChainValidation: false,
        handshakeTimeoutMs: 10000,
        alertDaysBeforeExpiry: 20,
        securityBaseline: {
            minTlsVersion: {
                value: "TLS1.2",
                severity: "fail",
            },
            minKeySizeBits: {
                value: 2048,
                severity: "fail",
            },
        },
        clientCertificate: {
            mode: "account_default",
        },
        assertions: [
            {
                source: "CERTIFICATE",
                property: "daysUntilExpiry",
                comparison: "GREATER_THAN",
                target: "14",
            },
            {
                source: "CONNECTION",
                property: "hostnameVerified",
                comparison: "EQUALS",
                target: "true",
            },
        ],
    },
});
